python3 -c "
import json, sys
with open('/work/output/artifacts/skill-flow-move-node/BellevueWeather/BellevueWeather/BellevueWeather.flow') as f:
    data = json.load(f)

nodes = {n['id']: n for n in data['nodes']}
edges = data['edges']

print('=== NODES ===')
for nid in nodes:
    print(f'  {nid}: {nodes[nid][\"type\"]}')

print()
print('=== EDGES ===')
for e in edges:
    print(f'  {e[\"id\"]}: {e[\"sourceNodeId\"]}:{e[\"sourcePort\"]} -> {e[\"targetNodeId\"]}:{e[\"targetPort\"]}')

print()
print('=== VALIDATION ===')
errors = []

# Check all edge source/target nodes exist
for e in edges:
    if e['sourceNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: source node {e[\"sourceNodeId\"]} not found')
    if e['targetNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: target node {e[\"targetNodeId\"]} not found')

# Check start node has outgoing edge
start_out = [e for e in edges if e['sourceNodeId'] == 'start']
if not start_out: errors.append('start node has no outgoing edges')

# Check end node has incoming edge
end_in = [e for e in edges if e['targetNodeId'] == 'end']
if not end_in: errors.append('end node has no incoming edges')

# Check decision node has both true and false ports used
decision_out = [e for e in edges if e['sourceNodeId'] == 'checkTemperature']
ports = [e['sourcePort'] for e in decision_out]
if 'true' not in ports: errors.append('checkTemperature missing true branch')
if 'false' not in ports: errors.append('checkTemperature missing false branch')

# Check formatSummary receives from both branches
fmt_in = [e for e in edges if e['targetNodeId'] == 'formatSummary']
print(f'formatSummary receives {len(fmt_in)} incoming edges (expected 2)')

# Check old nodes gone
for old in ['endNiceDay', 'endBringJacket']:
    if old in nodes: errors.append(f'{old} still present')

if errors:
    for err in errors:
        print(f'ERROR: {err}')
    sys.exit(1)
else:
    print('All checks passed!')
"

